{
  "positionId": "P05",
  "interviews": [
    {
      "categoryId": "P05-C2",
      "itemId": "P05-C2-I1",
      "interviewBlueprint": {
        "questionIntent": "거래처 분석 결과를 재접촉 캠페인의 타깃 우선순위로 구체화한 판단을 확인한다. 분석에서 확인한 사실이 실행 대상 선정으로 이어진 근거에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "오름퍼니처에서 장기간 발주가 없는 거래처를 대상으로 재접촉 캠페인을 수행한 상황이다.",
          "task": "거래처 분석 결과를 바탕으로 먼저 연락할 대상을 정해야 했다.",
          "action": "거래처 데이터에서 확인한 특징을 해석하고 이를 연락 우선순위의 기준으로 구체화한 판단을 설명한다.",
          "result": "분석 결과와 실제 연락 우선순위 사이의 연결이 구체적으로 드러난다."
        },
        "expectedEvidence": [
          "재접촉할 거래처의 우선순위를 정한 분석 근거",
          "해당 근거를 뒷받침하는 거래처 데이터의 구체적인 특징",
          "분석에서 확인한 특징이 연락 순서로 이어진 판단 논리"
        ]
      },
      "question": "오름퍼니처에서 6개월 이상 발주 없는 거래처에 재접촉하셨던데요, 연락할 거래처의 우선순위는 어떤 분석 결과를 근거로 정하셨어요?",
      "answerTip": "당시의 경험을 차분히 떠올려 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "우선순위를 정한 분석 근거를 구체적인 거래처 데이터의 특징으로 설명한다.",
            "데이터에서 확인한 특징이 특정 거래처를 먼저 연락할 대상으로 정한 판단에 연결된다."
          ]
        },
        "acceptable": {
          "criteria": [
            "분석 결과를 바탕으로 연락 우선순위를 정했다고 설명하지만, 근거가 된 데이터의 특징이 구체적이지 않다.",
            "분석 근거와 연락 순서의 연결은 확인되지만, 그 순서가 타당한 이유는 충분히 설명하지 못한다."
          ]
        },
        "poor": {
          "criteria": [
            "연락 우선순위를 정한 분석 근거를 제시하지 못한다.",
            "거래처 데이터나 재주문 성과만 언급하고 실제 연락 순서와의 연결을 설명하지 못한다."
          ]
        }
      }
    },
    {
      "categoryId": "P05-C2",
      "itemId": "P05-C2-I2",
      "interviewBlueprint": {
        "questionIntent": "캠페인의 성과 지표를 해석해 개선 방향을 정할 수 있는지 확인한다. 게시물 유형별 반응 지표에서 광고 소재 변경의 근거를 도출한 판단에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "동네 꽃집 인스타그램 광고에서 게시물 유형별 클릭과 문의 DM 수를 비교한 상황이다.",
          "task": "비교한 성과 지표를 근거로 광고 소재 변경의 필요성을 판단해야 했다.",
          "action": "판단에 사용한 지표의 의미와 게시물 유형별 차이를 해석해 소재 변경의 근거를 설명한다.",
          "result": "성과 지표의 해석이 소재 변경 결정으로 이어진 이유가 구체적으로 드러난다."
        },
        "expectedEvidence": [
          "광고 소재 변경을 결정한 성과 지표상의 근거",
          "판단에 사용한 지표가 나타내는 고객 반응의 의미",
          "게시물 유형별 지표 차이와 소재 변경 결정 사이의 연결"
        ]
      },
      "question": "동네 꽃집 인스타그램 광고 소액 집행 분석에서 게시물 유형별 반응을 비교하셨던데요, 성과 지표에서 무엇을 보고 소재 변경을 결정하셨어요?",
      "answerTip": "기억나는 장면을 중심으로 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "소재 변경의 근거가 된 지표와 게시물 유형별 차이를 구체적으로 설명한다.",
            "해당 지표가 나타내는 고객 반응을 해석하고, 그 해석이 소재 변경 결정으로 이어진 이유를 명확히 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "소재 변경의 근거로 사용한 지표와 반응 차이는 제시하지만, 차이에 대한 설명이 구체적이지 않다.",
            "지표와 소재 변경의 연결은 확인되지만, 지표가 나타내는 고객 반응의 의미는 충분히 설명하지 못한다."
          ]
        },
        "poor": {
          "criteria": [
            "소재 변경을 결정한 지표상의 근거를 제시하지 못한다.",
            "지표를 나열하거나 소재를 바꿨다는 사실만 말하고, 지표 해석과 변경 결정의 연결을 설명하지 못한다."
          ]
        }
      }
    }
  ]
}
